using MediatR; using JTradeERP.Application.Common.Persistence; using JTradeERP.Application.Common.Exceptions;
namespace JTradeERP.Application.Features.MasterData.UnitsOfMeasure.UpdateUnitOfMeasure;
public sealed class UpdateUnitOfMeasureHandler(IApplicationDbContext db) : IRequestHandler<UpdateUnitOfMeasureCommand,UpdateUnitOfMeasureResponse> { public async Task<UpdateUnitOfMeasureResponse> Handle(UpdateUnitOfMeasureCommand r,CancellationToken ct){var e=db.UnitsOfMeasure.SingleOrDefault(x=>x.Id==r.Id)??throw new NotFoundException("Unit of Measure not found.");if(db.UnitsOfMeasure.Any(x=>x.Id!=r.Id&&(x.Code==r.Code.Trim()||x.Name==r.Name.Trim())))throw new ConflictException("Unit of Measure already exists.");e.Update(r.Code,r.Name);await db.SaveChangesAsync(ct);return new(e.Id,e.Code,e.Name);} }
